  assertTrue(equals(indexedOrderBook, overwrite1244));
  // --------------------------------------------------------------------------------------------------------------------
  // a zero size delta for an id that is not in the book stores nothing, so the
  // constructor must not advance the length on its account. it used to, which
  // left the side with trailing holes and a length that overcounted the rows,
  // and limit() then dereferenced one of those holes
  ccxt::ws::WsOrderBook noopDeltas = ccxt::ws::indexedOrderBook(
      ccxt::dict{
          {std::string("bids"),
           ccxt::list{ccxt::list{100, 1, std::string("a")},
                      ccxt::list{101, 0, std::string("ghost")},
                      ccxt::list{102, 1, std::string("c")}}},
          {std::string("asks"),
           ccxt::list{ccxt::list{200, 0, std::string("ghost")},
                      ccxt::list{201, 1, std::string("d")}}},
      },
      2);
  assertTrue(
      isEqual(getArrayLength(::getValue(noopDeltas, std::string("bids"))), 2));
  assertTrue(
      isEqual(getArrayLength(::getValue(noopDeltas, std::string("asks"))), 1));
  assertTrue(!isEqual(
      ::getValue(::getValue(noopDeltas, std::string("bids")), 0), std::any{}));
  assertTrue(!isEqual(
      ::getValue(::getValue(noopDeltas, std::string("bids")), 1), std::any{}));
  assertTrue(!isEqual(
      ::getValue(::getValue(noopDeltas, std::string("asks")), 0), std::any{}));
  ::wsLimit(noopDeltas);
  assertTrue(
      isEqual(getArrayLength(::getValue(noopDeltas, std::string("bids"))), 2));
  assertTrue(
      isEqual(getArrayLength(::getValue(noopDeltas, std::string("asks"))), 1));
  // --------------------------------------------------------------------------------------------------------------------
