  ::wsLimit(countedOrderBook);
  assertTrue(equals(countedOrderBook, countedOrderBookTarget));
  ::wsStoreArray(countedBids, ccxt::list{1, 1, 6});
  ::wsLimit(countedOrderBook);
  assertTrue(equals(countedOrderBook, storedCountedOrderbookTarget));
  // --------------------------------------------------------------------------------------------------------------------
